    const path = missingProperty ? `${instancePath || ''}/${missingProperty}` : instancePath || '(root)';
    const message = error?.message ?? 'is invalid';
    log.warn('tool', 'input validation failed', {name, path, message});
    return {result: `Tool '${definition.name}' input invalid: ${path} ${message}`};
  }
}

